#include <stdio.h>
#include <string.h>
int main() {
    char s1[1000], s2[1000];
    if (fgets(s1, sizeof(s1), stdin) && fgets(s2, sizeof(s2), stdin)) {
        int l1 = strlen(s1), l2 = strlen(s2);
        while (l1 > 0 && (s1[l1-1] == '\n' || s1[l1-1] == '\r')) s1[--l1] = '\0';
        while (l2 > 0 && (s2[l2-1] == '\n' || s2[l2-1] == '\r')) s2[--l2] = '\0';
        printf("%s %s\n", s1, s2);
    }
    return 0;
}

